228→  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Chat send handler with streaming and tool calls
229→  const handleSendWithContent = async (messageContent: string) => {
230→    if (!messageContent.trim() || isSending) return;
231→
232→    setInput('');
233→    setIsSending(true);
234→    setStreamingContent('');
235→    setError(null);
236→    setToolCalls([]);
237→    setStatusMessage(null);
238→
239→    // Create AbortController for this request
240→    const controller = new AbortController();
241→    abortControllerRef.current = controller;
242→
243→    // Optimistically add user message
244→    const userMessage: Message = {
245→      id: `temp-${Date.now()}`,
246→      role: 'USER',
247→      content: messageContent,
248→      createdAt: new Date().toISOString(),
249→    };
250→    setMessages((prev) => [...prev, userMessage]);
251→
252→    // Track accumulated data for constructing final message
253→    let accumulatedContent = '';
254→    let completedToolCalls: ToolCall[] = [];
255→
256→    try {
257→      const response = await fetch(`/api/omega/conversations/${conversationId}/messages`, {
258→        method: 'POST',
259→        headers: { 'Content-Type': 'application/json' },
260→        body: JSON.stringify({ message: messageContent }),
261→        signal: controller.signal,
262→      });
263→
264→      if (!response.ok) {
265→        // Handle non-JSON error responses gracefully
266→        let errorMessage = 'Failed to send message';
267→        try {
268→          const errorData = await response.json();
269→          errorMessage = errorData.error || errorMessage;
270→        } catch {
271→          // Response body isn't valid JSON - use status text
272→          errorMessage = `Server error: ${response.status} ${response.statusText}`;
273→        }
274→        throw new Error(errorMessage);
275→      }
276→
277→      // Handle SSE stream
278→      const reader = response.body?.getReader();
279→      if (!reader) throw new Error('No response body');
280→
281→      const decoder = new TextDecoder();
282→      let buffer = '';
283→
284→      while (true) {
285→        const { done, value } = await reader.read();
286→        if (done) break;
287→
288→        buffer += decoder.decode(value, { stream: true });
289→
290→        // Parse SSE events
291→        const lines = buffer.split('\n');
292→        buffer = lines.pop() || ''; // Keep incomplete line in buffer
293→
294→        let eventType = '';
295→        for (const line of lines) {
296→          if (line.startsWith('event: ')) {
297→            eventType = line.slice(7);
298→          } else if (line.startsWith('data: ')) {
299→            // SSE parse safety: wrap JSON.parse in try/catch
300→            let data: unknown;
301→            try {
302→              data = JSON.parse(line.slice(6));
303→            } catch {
304→              console.warn('Failed to parse SSE data:', line.slice(6));
305→              continue;
306→            }
307→
308→            const d = data as Record<string, unknown>;
309→
310→            switch (eventType) {
311→              case 'status':
312→                // Display status messages from the server
313→                if (d.message && typeof d.message === 'string') {
314→                  setStatusMessage(d.message);
315→                }
316→                break;
317→              case 'env.warning':
318→                // Set environment variable warnings
319→                if (d.missingEnvVars && Array.isArray(d.missingEnvVars)) {
320→                  setEnvWarnings(d.missingEnvVars as EnvVarWarning[]);
321→                }
322→                break;
323→              case 'message.delta':
324→                setStatusMessage(null);
325→                accumulatedContent += (d as { content: string }).content;
326→                setStreamingContent((prev) => prev + (d as { content: string }).content);
327→                break;
328→              case 'run.step.tool.started':
329→                setStatusMessage(null);
330→                // Add tool call to tracking
331→                setToolCalls((prev) => {
332→                  const updated = [
333→                    ...prev,
334→                    {
335→                      toolCallId: d.toolCallId as string,
336→                      toolName: d.toolName as string,
337→                      input: d.input,
338→                      status: 'running' as const,
339→                    },
340→                  ];
341→                  completedToolCalls = updated;
342→                  return updated;
343→                });
344→                break;
345→              case 'run.step.tool.completed':
346→                // Update tool call with result
347→                setToolCalls((prev) => {
348→                  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool call update logic
349→                  const updated = prev.map((tc) =>
350→                    tc.toolCallId === d.toolCallId
351→                      ? {
352→                          ...tc,
353→                          output: d.output,
354→                          status: d.isError ? ('error' as const) : ('success' as const),
355→                          isError: d.isError as boolean | undefined,
356→                        }
357→                      : tc
358→                  );
359→                  completedToolCalls = updated;
360→                  return updated;
361→                });
362→                break;
363→              case 'run.completed': {
364→                // Build the assistant message from accumulated SSE data
365→                const assistantMessage: Message = {
366→                  id: (d.messageId as string) || `msg-${Date.now()}`,
367→                  role: 'ASSISTANT',
368→                  content: accumulatedContent,
369→                  toolCalls: completedToolCalls
370→                    .filter((tc) => tc.status === 'success' || tc.status === 'error')
371→                    .map((tc) => ({
372→                      toolCallId: tc.toolCallId,
373→                      toolName: tc.toolName,
374→                      args: tc.input,
375→                      output: tc.output,
376→                    })),
377→                  inputTokens: d.inputTokens as number,
378→                  outputTokens: d.outputTokens as number,
379→                  createdAt: new Date().toISOString(),
380→                };
381→
382→                // Build tool results message if there were tool calls
383→                const toolResultEntries = completedToolCalls
384→                  .filter((tc) => tc.output !== undefined)
385→                  .map((tc) => ({
386→                    toolCallId: tc.toolCallId,
387→                    toolName: tc.toolName,
388→                    output: tc.output,
389→                  }));
390→
391→                setMessages((prev) => {
392→                  const updated = [...prev, assistantMessage];
393→                  if (toolResultEntries.length > 0) {
394→                    updated.push({
395→                      id: `tool-${Date.now()}`,
396→                      role: 'TOOL',
397→                      content: 'Tool results',
398→                      toolCalls: toolResultEntries,
399→                      createdAt: new Date().toISOString(),
400→                    });
401→                  }
402→                  return updated;
403→                });
404→
405→                // Update conversation token totals locally
406→                if (conversation) {
407→                  setConversation({
408→                    ...conversation,
409→                    inputTokensTotal:
410→                      conversation.inputTokensTotal + ((d.inputTokens as number) || 0),
411→                    outputTokensTotal:
412→                      conversation.outputTokensTotal + ((d.outputTokens as number) || 0),
413→                    executionState: 'idle',
414→                  });
415→                }
416→
417→                // Associate tool discovery info
418→                const toolDiscovery: ToolDiscoveryInfo = {
419→                  staticTools: d.staticTools as string[],
420→                  dynamicToolsLoaded: d.dynamicToolsLoaded as string[],
421→                  autoDiscoveredTools:
422→                    d.autoDiscoveredTools as ToolDiscoveryInfo['autoDiscoveredTools'],
423→                };
424→                setMessageToolDiscovery((prev) => {
425→                  const next = new Map(prev);
426→                  next.set(assistantMessage.id, toolDiscovery);
427→                  return next;
428→                });
429→
430→                setStreamingContent('');
431→                setToolCalls([]);
432→                setStatusMessage(null);
433→                break;
434→              }
435→              case 'run.failed':
436→                throw new Error(d.error as string);
437→            }
438→          }
439→        }
440→      }
441→    } catch (err) {
442→      // Handle AbortError gracefully (user clicked stop)
