450→      setMessages((prev) => prev.filter((m) => m.id !== userMessage.id));
451→    } finally {
452→      abortControllerRef.current = null;
453→      setIsSending(false);
454→      setStreamingContent('');
455→      setStatusMessage(null);
456→      inputRef.current?.focus();
457→    }
