  1→'use client';
  2→
  3→import { cn } from '@tpmjs/utils/cn';
  4→import { forwardRef, useEffect } from 'react';
  5→import { useCountUp } from '../system/hooks/useCountUp';
  6→import { useScrollReveal } from '../system/hooks/useScrollReveal';
  7→import type { AnimatedCounterProps } from './types';
  8→import { animatedCounterVariants } from './variants';
  9→
 10→/**
 11→ * AnimatedCounter component
 12→ *
 13→ * Displays an animated number counter with customizable formatting.
 14→ * Can start animation on mount or when scrolled into viewport.
 15→ *
 16→ * @example
 17→ * ```tsx
 18→ * import { AnimatedCounter } from '@tpmjs/ui/AnimatedCounter/AnimatedCounter';
 19→ *
 20→ * function Stats() {
 21→ *   return (
 22→ *     <div>
 23→ *       <AnimatedCounter value={2847} suffix=" Tools" size="xl" />
 24→ *       <AnimatedCounter value={12000000} suffix="+" prefix="" size="lg" />
 25→ *     </div>
 26→ *   );
 27→ * }
 28→ * ```
 29→ */
 30→export const AnimatedCounter = forwardRef<HTMLSpanElement, AnimatedCounterProps>(
 31→  (
 32→    {
 33→      className,
 34→      value,
 35→      duration = 2000,
 36→      decimals = 0,
 37→      prefix = '',
 38→      suffix = '',
 39→      separator = '',
 40→      startOn = 'viewport',
 41→      easing = 'easeOutExpo',
 42→      size = 'md',
 43→      mono = true,
 44→      ...props
 45→    },
 46→    ref
 47→  ) => {
 48→    const { count, start } = useCountUp({
 49→      end: value,
 50→      duration,
 51→      decimals,
 52→      easing,
 53→      autoStart: startOn === 'mount',
 54→    });
 55→
 56→    const { ref: scrollRef, isVisible } = useScrollReveal({
 57→      threshold: 0.2,
 58→      once: true,
 59→    });
 60→
 61→    // Start animation when element becomes visible (if startOn === 'viewport')
 62→    useEffect(() => {
 63→      if (startOn === 'viewport' && isVisible) {
 64→        start();
 65→      }
 66→    }, [isVisible, start, startOn]);
 67→
 68→    // Format number with separator if provided
 69→    const formatNumber = (num: number): string => {
 70→      const numStr = num.toFixed(decimals);
 71→      if (!separator) return numStr;
 72→
 73→      const parts = numStr.split('.');
 74→      const intPart = parts[0];
 75→      const decPart = parts[1];
 76→      const formattedInt = intPart ? intPart.replace(/\B(?=(\d{3})+(?!\d))/g, separator) : '';
 77→      return decPart ? `${formattedInt}.${decPart}` : formattedInt;
 78→    };
 79→
 80→    const formattedValue = formatNumber(count);
 81→
 82→    return (
 83→      <span
 84→        ref={(node) => {
 85→          // Assign to both refs - this is a standard ref callback pattern for merging refs
 86→          if (scrollRef) {
 87→            // eslint-disable-next-line react-hooks/immutability
 88→            (scrollRef as React.MutableRefObject<HTMLSpanElement | null>).current = node;
 89→          }
 90→          if (typeof ref === 'function') {
 91→            ref(node);
 92→          } else if (ref) {
 93→            ref.current = node;
 94→          }
 95→        }}
 96→        className={cn(
 97→          animatedCounterVariants({
 98→            size,
 99→            mono: mono ? 'true' : 'false',
100→          }),
101→          className
102→        )}
103→        aria-label={`${prefix}${value}${suffix}`}
104→        {...props}
105→      >
106→        {prefix}
107→        {formattedValue}
108→        {suffix}
109→      </span>
110→    );
111→  }
112→);
113→
114→AnimatedCounter.displayName = 'AnimatedCounter';
115→

 1→import { cn } from '@tpmjs/utils/cn';
