19→ */
20→export const Badge = forwardRef<HTMLDivElement, BadgeProps>(
21→  ({ className, variant = 'default', size = 'md', ...props }, ref) => {
22→    return (
23→      <div
24→        ref={ref}
25→        className={cn(
26→          badgeVariants({
27→            variant,
28→            size,
29→          }),
