  1→import { cn } from '@tpmjs/utils/cn';
  2→import { forwardRef, useMemo } from 'react';
  3→import type { TextareaProps } from './types';
  4→import { textareaVariants } from './variants';
  5→
  6→/**
  7→ * Textarea component
  8→ *
  9→ * A multi-line text input component with support for character counting,
 10→ * different states, sizes, and resize behaviors.
 11→ *
 12→ * @example
 13→ * ```tsx
 14→ * import { Textarea } from '@tpmjs/ui/Textarea/Textarea';
 15→ *
 16→ * function MyComponent() {
 17→ *   return (
 18→ *     <Textarea
 19→ *       placeholder="Enter your message..."
 20→ *       rows={5}
 21→ *       maxLength={500}
 22→ *       showCount
 23→ *       state="default"
 24→ *       size="md"
 25→ *     />
 26→ *   );
 27→ * }
 28→ * ```
 29→ */
 30→export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(
 31→  (
 32→    {
 33→      className,
 34→      state = 'default',
 35→      size = 'md',
 36→      fullWidth = true,
 37→      resize = 'vertical',
 38→      showCount = false,
 39→      maxLength,
 40→      value,
 41→      defaultValue,
 42→      disabled = false,
 43→      ...props
 44→    },
 45→    ref
 46→  ) => {
 47→    // Calculate character count for display
 48→    const characterCount = useMemo(() => {
 49→      if (!showCount) return null;
 50→
 51→      const currentValue = value ?? defaultValue ?? '';
 52→      const current =
 53→        typeof currentValue === 'string' ? currentValue.length : String(currentValue).length;
 54→
 55→      return {
 56→        current,
 57→        max: maxLength,
 58→      };
 59→    }, [showCount, value, defaultValue, maxLength]);
 60→
 61→    return (
 62→      <div className={cn('relative', fullWidth && 'w-full')}>
 63→        <textarea
 64→          ref={ref}
 65→          className={cn(
 66→            textareaVariants({
 67→              state,
 68→              size,
 69→              fullWidth: fullWidth ? 'true' : 'false',
 70→              resize,
 71→            }),
 72→            className
 73→          )}
 74→          disabled={disabled}
 75→          maxLength={maxLength}
 76→          value={value}
 77→          defaultValue={defaultValue}
 78→          aria-invalid={state === 'error' ? 'true' : undefined}
 79→          {...props}
 80→        />
 81→
 82→        {/* Character counter */}
 83→        {showCount && characterCount && (
 84→          <div
 85→            className={cn(
 86→              'mt-1.5 text-xs',
 87→              state === 'error' ? 'text-error' : 'text-foreground-secondary',
 88→              'transition-colors duration-200'
 89→            )}
 90→            aria-live="polite"
 91→            aria-atomic="true"
 92→          >
 93→            {characterCount.current}
 94→            {characterCount.max !== undefined && (
 95→              <>
 96→                <span className="text-foreground-tertiary"> / </span>
 97→                {characterCount.max}
 98→              </>
 99→            )}
100→          </div>
101→        )}
102→      </div>
103→    );
104→  }
105→);
106→
107→Textarea.displayName = 'Textarea';
