 3→import { useEffect, useState } from 'react';
 4→
 5→export interface GlitchBarsProps {
 6→  /**
 7→   * Number of bars to render
 8→   * @default 3
 9→   */
10→  count?: number;
11→
12→  /**
13→   * Minimum interval between glitches (ms)
14→   * @default 2000
15→   */
16→  minInterval?: number;
17→
18→  /**
19→   * Maximum interval between glitches (ms)
20→   * @default 5000
21→   */
22→  maxInterval?: number;
23→}
24→
25→/**
26→ * GlitchBars Component
27→ *
28→ * Renders decorative horizontal bars that randomly glitch/shift position.
29→ * Pure visual element for brutalist aesthetic.
30→ */
31→export function GlitchBars({
32→  count = 3,
33→  minInterval = 2000,
34→  maxInterval = 5000,
35→}: GlitchBarsProps): React.ReactElement {
36→  const [activeBar, setActiveBar] = useState<number | null>(null);
37→
38→  useEffect(() => {
39→    const triggerGlitch = (): void => {
40→      const randomBar = Math.floor(Math.random() * count);
41→      setActiveBar(randomBar);
42→
43→      // Reset after glitch animation completes
44→      setTimeout(() => {
45→        setActiveBar(null);
46→      }, 500);
47→
48→      // Schedule next glitch
49→      const nextInterval = minInterval + Math.random() * (maxInterval - minInterval);
50→      setTimeout(triggerGlitch, nextInterval);
51→    };
52→
53→    const initialDelay = Math.random() * 2000;
54→    const timeout = setTimeout(triggerGlitch, initialDelay);
55→
56→    return () => {
57→      clearTimeout(timeout);
58→    };
59→  }, [count, minInterval, maxInterval]);
60→
61→  return (
62→    <div className="pointer-events-none absolute inset-0 overflow-hidden" aria-hidden="true">
63→      {Array.from({ length: count }).map((_, index) => {
64→        const top = 20 + index * 25; // Distribute vertically
65→        const width = 100 + index * 50; // Varying widths
66→        const isLeft = index % 2 === 0;
67→
68→        return (
69→          <div
