 1→'use client';
 2→
 3→import { Button } from '@tpmjs/ui/Button/Button';
 4→import { Icon } from '@tpmjs/ui/Icon/Icon';
 5→import { useRouter } from 'next/navigation';
 6→import { useState } from 'react';
 7→
 8→interface EnvVarWarning {
 9→  toolId: string;
10→  toolName: string;
11→  packageName: string;
12→  envVar: {
13→    name: string;
14→    description: string;
15→    required: boolean;
16→  };
17→}
18→
19→interface EnvVarWarningBannerProps {
20→  warnings: EnvVarWarning[];
21→  onDismiss?: () => void;
22→}
23→
24→/**
25→ * Warning banner displayed when tools need API keys that aren't configured
26→ */
27→export function EnvVarWarningBanner({ warnings, onDismiss }: EnvVarWarningBannerProps) {
28→  const router = useRouter();
29→  const [isDismissed, setIsDismissed] = useState(false);
30→
31→  if (isDismissed || warnings.length === 0) {
32→    return null;
33→  }
34→
35→  // Group warnings by env var name
36→  const uniqueEnvVars = Array.from(new Map(warnings.map((w) => [w.envVar.name, w])).values());
37→
38→  const handleConfigure = () => {
39→    router.push('/omega/settings');
40→  };
41→
42→  const handleDismiss = () => {
