139→    try {
140→      const response = await fetch(`/api/omega/conversations/${conversationId}`);
141→
142→      if (response.status === 404) {
143→        setError('Conversation not found');
144→        setIsLoading(false);
145→        return;
146→      }
147→
148→      if (!response.ok) {
149→        const data = await response.json();
150→        throw new Error(data.error || 'Failed to fetch conversation');
151→      }
152→
153→      const data = await response.json();
154→      const { messages: messageList, ...conversationData } = data.data;
155→      setConversation(conversationData);
156→      setMessages(messageList || []);
157→    } catch (err) {
158→      console.error('Failed to fetch conversation:', err);
159→      setError(err instanceof Error ? err.message : 'Failed to fetch conversation');
160→    } finally {
161→      setIsLoading(false);
162→    }
163→  }, [conversationId]);
164→
165→  useEffect(() => {
166→    fetchConversation();
167→  }, [fetchConversation]);
168→
169→  // Smart auto-scroll
170→  const handleScroll = useCallback(() => {
