235→    const userMessage: Message = {
236→      id: `temp-${Date.now()}`,
237→      role: 'USER',
238→      content: messageContent,
239→      createdAt: new Date().toISOString(),
240→    };
241→    setMessages((prev) => [...prev, userMessage]);
242→
243→    let accumulatedContent = '';
244→    let completedToolCalls: ToolCall[] = [];
245→
246→    try {
247→      const response = await fetch(`/api/omega/conversations/${conversationId}/messages`, {
248→        method: 'POST',
249→        headers: { 'Content-Type': 'application/json' },
250→        body: JSON.stringify({ message: messageContent }),
251→        signal: controller.signal,
252→      });
253→
254→      if (!response.ok) {
255→        let errorMessage = 'Failed to send message';
256→        try {
257→          const errorData = await response.json();
258→          errorMessage = errorData.error || errorMessage;
259→        } catch {
260→          errorMessage = `Server error: ${response.status} ${response.statusText}`;
261→        }
262→        throw new Error(errorMessage);
263→      }
264→
265→      const reader = response.body?.getReader();
266→      if (!reader) throw new Error('No response body');
267→
268→      const decoder = new TextDecoder();
269→      let buffer = '';
270→
271→      while (true) {
272→        const { done, value } = await reader.read();
273→        if (done) break;
274→
275→        buffer += decoder.decode(value, { stream: true });
276→
277→        const lines = buffer.split('\n');
278→        buffer = lines.pop() || '';
279→
280→        let eventType = '';
281→        for (const line of lines) {
282→          if (line.startsWith('event: ')) {
283→            eventType = line.slice(7);
284→          } else if (line.startsWith('data: ')) {
285→            let data: unknown;
286→            try {
287→              data = JSON.parse(line.slice(6));
288→            } catch {
289→              console.warn('Failed to parse SSE data:', line.slice(6));
290→              continue;
291→            }
292→
293→            const d = data as Record<string, unknown>;
294→
295→            switch (eventType) {
296→              case 'status':
297→                if (d.message && typeof d.message === 'string') {
298→                  setStatusMessage(d.message);
299→                }
300→                break;
301→              case 'env.warning':
302→                if (d.missingEnvVars && Array.isArray(d.missingEnvVars)) {
303→                  setEnvWarnings(d.missingEnvVars as EnvVarWarning[]);
304→                }
305→                break;
306→              case 'message.delta':
307→                setStatusMessage(null);
308→                accumulatedContent += (d as { content: string }).content;
309→                setStreamingContent((prev) => prev + (d as { content: string }).content);
310→                break;
311→              case 'run.step.tool.started':
312→                setStatusMessage(null);
313→                setToolCalls((prev) => {
314→                  const updated = [
315→                    ...prev,
316→                    {
317→                      toolCallId: d.toolCallId as string,
318→                      toolName: d.toolName as string,
319→                      input: d.input,
320→                      status: 'running' as const,
321→                    },
322→                  ];
323→                  completedToolCalls = updated;
324→                  return updated;
325→                });
326→                break;
327→              case 'run.step.tool.completed':
328→                setToolCalls((prev) => {
329→                  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool call update logic
330→                  const updated = prev.map((tc) =>
331→                    tc.toolCallId === d.toolCallId
332→                      ? {
333→                          ...tc,
334→                          output: d.output,
335→                          status: d.isError ? ('error' as const) : ('success' as const),
336→                          isError: d.isError as boolean | undefined,
337→                        }
338→                      : tc
339→                  );
340→                  completedToolCalls = updated;
341→                  return updated;
342→                });
343→                break;
344→              case 'run.completed': {
345→                const assistantMessage: Message = {
346→                  id: (d.messageId as string) || `msg-${Date.now()}`,
347→                  role: 'ASSISTANT',
348→                  content: accumulatedContent,
349→                  toolCalls: completedToolCalls
350→                    .filter((tc) => tc.status === 'success' || tc.status === 'error')
351→                    .map((tc) => ({
352→                      toolCallId: tc.toolCallId,
353→                      toolName: tc.toolName,
354→                      args: tc.input,
355→                      output: tc.output,
356→                    })),
357→                  inputTokens: d.inputTokens as number,
358→                  outputTokens: d.outputTokens as number,
359→                  createdAt: new Date().toISOString(),
360→                };
361→
362→                const toolResultEntries = completedToolCalls
363→                  .filter((tc) => tc.output !== undefined)
364→                  .map((tc) => ({
365→                    toolCallId: tc.toolCallId,
366→                    toolName: tc.toolName,
367→                    output: tc.output,
368→                  }));
369→
370→                setMessages((prev) => {
371→                  const updated = [...prev, assistantMessage];
372→                  if (toolResultEntries.length > 0) {
373→                    updated.push({
374→                      id: `tool-${Date.now()}`,
375→                      role: 'TOOL',
376→                      content: 'Tool results',
377→                      toolCalls: toolResultEntries,
378→                      createdAt: new Date().toISOString(),
379→                    });
380→                  }
381→                  return updated;
382→                });
383→
384→                if (conversation) {
385→                  setConversation({
386→                    ...conversation,
387→                    inputTokensTotal:
388→                      conversation.inputTokensTotal + ((d.inputTokens as number) || 0),
389→                    outputTokensTotal:
390→                      conversation.outputTokensTotal + ((d.outputTokens as number) || 0),
391→                    executionState: 'idle',
392→                  });
393→                }
394→
395→                const toolDiscovery: ToolDiscoveryInfo = {
396→                  staticTools: d.staticTools as string[],
397→                  dynamicToolsLoaded: d.dynamicToolsLoaded as string[],
398→                  autoDiscoveredTools:
399→                    d.autoDiscoveredTools as ToolDiscoveryInfo['autoDiscoveredTools'],
400→                };
401→                setMessageToolDiscovery((prev) => {
402→                  const next = new Map(prev);
403→                  next.set(assistantMessage.id, toolDiscovery);
404→                  return next;
405→                });
406→
407→                setStreamingContent('');
408→                setToolCalls([]);
409→                setStatusMessage(null);
410→                break;
411→              }
412→              case 'run.failed':
413→                throw new Error(d.error as string);
414→            }
415→          }
416→        }
417→      }
418→    } catch (err) {
419→      if (err instanceof DOMException && err.name === 'AbortError') {
420→        return;
421→      }
422→      console.error('Failed to send message:', err);
423→      setError(err instanceof Error ? err.message : 'Failed to send message');
