 12→interface DropdownItem {
 13→  href: string;
 14→  label: string;
 15→  description?: string;
 16→  external?: boolean;
 17→}
 18→
 19→interface NavDropdownProps {
 20→  label: string;
 21→  items: DropdownItem[];
 22→}
 23→
 24→function NavDropdown({ label, items }: NavDropdownProps): React.ReactElement {
 25→  const [isOpen, setIsOpen] = useState(false);
 26→  const [focusedIndex, setFocusedIndex] = useState(-1);
 27→  const dropdownRef = useRef<HTMLDivElement>(null);
 28→  const menuRef = useRef<HTMLDivElement>(null);
 29→  const buttonRef = useRef<HTMLButtonElement>(null);
 30→
 31→  useEffect(() => {
 32→    function handleClickOutside(event: MouseEvent) {
 33→      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
 34→        setIsOpen(false);
 35→        setFocusedIndex(-1);
 36→      }
 37→    }
 38→    document.addEventListener('mousedown', handleClickOutside);
 39→    return () => document.removeEventListener('mousedown', handleClickOutside);
 40→  }, []);
 41→
 42→  // Focus menu item when focusedIndex changes
 43→  useEffect(() => {
 44→    if (isOpen && focusedIndex >= 0 && menuRef.current) {
 45→      const menuItems = menuRef.current.querySelectorAll<HTMLElement>('[role="menuitem"]');
 46→      menuItems[focusedIndex]?.focus();
 47→    }
 48→  }, [focusedIndex, isOpen]);
 49→
 50→  const handleKeyDown = (event: React.KeyboardEvent) => {
 51→    switch (event.key) {
 52→      case 'Escape':
 53→        setIsOpen(false);
 54→        setFocusedIndex(-1);
 55→        buttonRef.current?.focus();
 56→        event.preventDefault();
 57→        break;
 58→      case 'ArrowDown':
 59→        event.preventDefault();
 60→        if (!isOpen) {
 61→          setIsOpen(true);
 62→          setFocusedIndex(0);
 63→        } else {
 64→          setFocusedIndex((prev) => (prev < items.length - 1 ? prev + 1 : 0));
 65→        }
 66→        break;
 67→      case 'ArrowUp':
 68→        event.preventDefault();
 69→        if (isOpen) {
 70→          setFocusedIndex((prev) => (prev > 0 ? prev - 1 : items.length - 1));
 71→        }
 72→        break;
 73→      case 'Tab':
 74→        if (isOpen) {
 75→          setIsOpen(false);
 76→          setFocusedIndex(-1);
 77→        }
 78→        break;
 79→    }
 80→  };
 81→
 82→  const handleItemClick = () => {
 83→    setIsOpen(false);
 84→    setFocusedIndex(-1);
 85→  };
 86→
 87→  return (
 88→    <div className="relative" ref={dropdownRef}>
 89→      <Button
 90→        ref={buttonRef}
 91→        variant="ghost"
 92→        size="sm"
 93→        className="text-foreground hover:text-foreground flex items-center gap-1"
 94→        onClick={() => {
 95→          setIsOpen(!isOpen);
 96→          if (!isOpen) setFocusedIndex(-1);
 97→        }}
 98→        onKeyDown={handleKeyDown}
 99→        aria-expanded={isOpen}
100→        aria-haspopup="menu"
101→      >
102→        {label}
103→        <Icon
104→          icon="chevronDown"
105→          size="sm"
106→          className={`transition-transform ${isOpen ? 'rotate-180' : ''}`}
107→        />
108→      </Button>
109→      {isOpen && (
110→        <div
111→          ref={menuRef}
112→          role="menu"
113→          aria-label={label}
114→          tabIndex={-1}
115→          onKeyDown={handleKeyDown}
116→          className="absolute top-full left-0 mt-1 w-56 bg-background border border-border rounded-lg shadow-lg py-1 z-50"
117→        >
118→          {items.map((item, index) =>
119→            item.external ? (
120→              <a
121→                key={item.href}
122→                href={item.href}
123→                target="_blank"
124→                rel="noopener noreferrer"
125→                role="menuitem"
126→                tabIndex={focusedIndex === index ? 0 : -1}
127→                className="flex items-center justify-between px-4 py-2 text-sm text-foreground hover:bg-surface focus:bg-surface focus:outline-none transition-colors"
128→                onClick={handleItemClick}
129→              >
130→                <div>
131→                  <div className="font-medium">{item.label}</div>
132→                  {item.description && (
133→                    <div className="text-xs text-foreground-tertiary">{item.description}</div>
134→                  )}
135→                </div>
136→                <Icon icon="externalLink" size="sm" className="text-foreground-tertiary" />
137→              </a>
138→            ) : (
139→              <Link
140→                key={item.href}
141→                href={item.href}
142→                role="menuitem"
143→                tabIndex={focusedIndex === index ? 0 : -1}
144→                className="block px-4 py-2 text-sm text-foreground hover:bg-surface focus:bg-surface focus:outline-none transition-colors"
145→                onClick={handleItemClick}
146→              >
147→                <div className="font-medium">{item.label}</div>
148→                {item.description && (
149→                  <div className="text-xs text-foreground-tertiary">{item.description}</div>
150→                )}
151→              </Link>
152→            )
153→          )}
154→        </div>
155→      )}
156→    </div>
157→  );
158→}
