 9→ * GET /api/admin/stats
10→ * Returns latest StatsSnapshot + trend data (last 30 snapshots)
11→ * Requires ADMIN role.
12→ */
13→export async function GET() {
14→  try {
15→    await requireAdmin();
16→  } catch (response) {
17→    if (response instanceof Response) return response;
18→    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
19→  }
20→
21→  try {
22→    const snapshots = await prisma.statsSnapshot.findMany({
23→      orderBy: { date: 'desc' },
24→      take: 30,
25→    });
26→
27→    const latest = snapshots[0] ?? null;
28→
29→    // Serialize BigInt fields
30→    const serialized = snapshots.map((s) => ({
31→      ...s,
32→      tokensInput: Number(s.tokensInput),
33→      tokensOutput: Number(s.tokensOutput),
34→      tokensTotal: Number(s.tokensTotal),
35→    }));
36→
37→    // Compute some summary stats
38→    const totalUsers = await prisma.user.count();
39→    const totalSessions = await prisma.session.count();
40→
41→    return NextResponse.json({
42→      success: true,
43→      data: {
44→        latest: latest
45→          ? {
46→              ...latest,
47→              tokensInput: Number(latest.tokensInput),
48→              tokensOutput: Number(latest.tokensOutput),
49→              tokensTotal: Number(latest.tokensTotal),
50→            }
51→          : null,
52→        trend: serialized.reverse(), // oldest first for charts
53→        totalUsers,
54→        totalSessions,
55→      },
56→    });
57→  } catch (error) {
58→    console.error('[Admin Stats Error]', error);
59→    return NextResponse.json(
60→      { success: false, error: error instanceof Error ? error.message : 'Unknown error' },
61→      { status: 500 }
62→    );
63→  }
64→}
