 93→ * Convert ToolCall to ToolPart for rendering
 94→ */
 95→function toolCallToToolPart(tc: ToolCall): ToolPart {
 96→  return {
 97→    type: tc.status === 'success' || tc.status === 'error' ? 'tool-result' : 'tool-call',
 98→    toolCallId: tc.toolCallId,
 99→    toolName: tc.toolName,
100→    args: tc.input,
101→    result: tc.isError ? { error: tc.output } : tc.output,
102→    state: statusToToolState(tc.status),
103→  };
104→}
