259→        } catch {
260→          errorMessage = `Server error: ${response.status} ${response.statusText}`;
261→        }
262→        throw new Error(errorMessage);
263→      }
264→
265→      const reader = response.body?.getReader();
266→      if (!reader) throw new Error('No response body');
267→
268→      const decoder = new TextDecoder();
269→      let buffer = '';
270→
271→      while (true) {
272→        const { done, value } = await reader.read();
273→        if (done) break;
274→
275→        buffer += decoder.decode(value, { stream: true });
276→
277→        const lines = buffer.split('\n');
278→        buffer = lines.pop() || '';
279→
280→        let eventType = '';
281→        for (const line of lines) {
282→          if (line.startsWith('event: ')) {
283→            eventType = line.slice(7);
284→          } else if (line.startsWith('data: ')) {
285→            let data: unknown;
