304→                }
305→                break;
306→              case 'message.delta':
307→                setStatusMessage(null);
308→                accumulatedContent += (d as { content: string }).content;
309→                setStreamingContent((prev) => prev + (d as { content: string }).content);
310→                break;
311→              case 'run.step.tool.started':
312→                setStatusMessage(null);
313→                setToolCalls((prev) => {
314→                  const updated = [
315→                    ...prev,
316→                    {
317→                      toolCallId: d.toolCallId as string,
318→                      toolName: d.toolName as string,
319→                      input: d.input,
320→                      status: 'running' as const,
321→                    },
322→                  ];
323→                  completedToolCalls = updated;
324→                  return updated;
325→                });
326→                break;
327→              case 'run.step.tool.completed':
328→                setToolCalls((prev) => {
329→                  // biome-ignore lint/complexity/noExcessiveCognitiveComplexity: Tool call update logic
330→                  const updated = prev.map((tc) =>
331→                    tc.toolCallId === d.toolCallId
332→                      ? {
333→                          ...tc,
334→                          output: d.output,
335→                          status: d.isError ? ('error' as const) : ('success' as const),
336→                          isError: d.isError as boolean | undefined,
337→                        }
338→                      : tc
339→                  );
340→                  completedToolCalls = updated;
341→                  return updated;
342→                });
343→                break;
344→              case 'run.completed': {
345→                const assistantMessage: Message = {
346→                  id: (d.messageId as string) || `msg-${Date.now()}`,
347→                  role: 'ASSISTANT',
348→                  content: accumulatedContent,
349→                  toolCalls: completedToolCalls
350→                    .filter((tc) => tc.status === 'success' || tc.status === 'error')
351→                    .map((tc) => ({
352→                      toolCallId: tc.toolCallId,
353→                      toolName: tc.toolName,
354→                      args: tc.input,
355→                      output: tc.output,
356→                    })),
357→                  inputTokens: d.inputTokens as number,
358→                  outputTokens: d.outputTokens as number,
359→                  createdAt: new Date().toISOString(),
360→                };
361→
362→                const toolResultEntries = completedToolCalls
363→                  .filter((tc) => tc.output !== undefined)
364→                  .map((tc) => ({
365→                    toolCallId: tc.toolCallId,
366→                    toolName: tc.toolName,
367→                    output: tc.output,
368→                  }));
369→
370→                setMessages((prev) => {
371→                  const updated = [...prev, assistantMessage];
372→                  if (toolResultEntries.length > 0) {
373→                    updated.push({
374→                      id: `tool-${Date.now()}`,
375→                      role: 'TOOL',
376→                      content: 'Tool results',
377→                      toolCalls: toolResultEntries,
378→                      createdAt: new Date().toISOString(),
379→                    });
380→                  }
