722→                      )}
723→
724→                      {message.toolCalls && message.toolCalls.length > 0 && (
725→                        <div className="pt-3 border-t border-border/50">
726→                          <div className="text-[10px] uppercase tracking-wider text-foreground-tertiary font-mono mb-2">
727→                            Tool Calls ({message.toolCalls.length})
728→                          </div>
729→                          <pre className="text-xs font-mono bg-background/50 p-3 overflow-x-auto whitespace-pre-wrap max-h-48 overflow-y-auto">
730→                            {JSON.stringify(message.toolCalls, null, 2)}
731→                          </pre>
732→                        </div>
733→                      )}
734→
735→                      {(message.inputTokens || message.outputTokens) && (
736→                        <div className="text-[10px] text-foreground-tertiary font-mono pt-2 border-t border-border/50">
737→                          {message.inputTokens && <span>Input: {message.inputTokens}</span>}
738→                          {message.inputTokens && message.outputTokens && <span> | </span>}
739→                          {message.outputTokens && <span>Output: {message.outputTokens}</span>}
740→                        </div>
741→                      )}
742→                    </div>
743→                  </div>
744→                );
745→              })}
746→
747→              {messages.length === 0 && (
748→                <div className="text-center py-8 text-foreground-tertiary font-mono text-sm">
749→                  No messages yet. Start a conversation to see debug data.
750→                </div>
751→              )}
752→            </div>
753→          </div>
754→        )}
755→
756→        {/* Chat View */}
757→        {viewMode === 'chat' && (
758→          <>
759→            {/* Messages */}
760→            <div className="flex-1 overflow-hidden">
761→              {messages.length === 0 && !streamingContent ? (
762→                /* Empty State */
763→                <div className="h-full flex items-center justify-center p-4">
764→                  <div className="text-center">
765→                    {/* Watermark */}
766→                    <div className="text-6xl md:text-8xl font-bold text-foreground/10 font-mono uppercase tracking-tighter mb-8 select-none">
767→                      OMEGA
768→                    </div>
769→
770→                    {/* Capability Icons */}
771→                    <div className="flex items-center justify-center gap-3 mb-6">
772→                      {CAPABILITY_ICONS.map((icon, i) => (
773→                        <div
774→                          key={icon}
