877→                      <div className="px-4 pb-4">
878→                        <div className="flex justify-start">
879→                          <div className="max-w-[80%] border-l-4 border-foreground/20 p-4 bg-surface-secondary">
880→                            <div className="text-sm prose prose-sm dark:prose-invert max-w-none">
881→                              <Streamdown>{streamingContent}</Streamdown>
882→                            </div>
883→                            <span className="inline-block w-2 h-4 bg-primary animate-pulse ml-1" />
884→                          </div>
885→                        </div>
886→                      </div>
887→                    )}
888→
889→                    {/* Thinking indicator */}
890→                    {isSending && !streamingContent && toolCalls.length === 0 && (
891→                      <div className="px-4 pb-4">
892→                        <div className="flex justify-start">
893→                          <div className="border-l-4 border-primary p-4 bg-surface-secondary">
894→                            <div className="flex items-center gap-2 text-foreground-secondary">
895→                              <div className="w-2 h-2 bg-primary animate-pulse" />
896→                              <span className="font-mono text-sm">
897→                                {statusMessage || 'discovering tools...'}
898→                              </span>
899→                            </div>
900→                          </div>
901→                        </div>
902→                      </div>
903→                    )}
904→                  </div>
905→                </div>
906→              )}
907→            </div>
908→
909→            {/* Environment Variable Warnings */}
