931→                    onKeyDown={handleKeyDown}
932→                    placeholder="Ask Omega anything..."
933→                    rows={1}
934→                    resize="none"
935→                    className="border-none bg-transparent flex-1 min-h-[48px] max-h-[200px]"
936→                    style={{
937→                      height: 'auto',
938→                      minHeight: '48px',
939→                    }}
940→                    onInput={(e) => {
941→                      const target = e.target as HTMLTextAreaElement;
942→                      target.style.height = 'auto';
943→                      target.style.height = `${Math.min(target.scrollHeight, 200)}px`;
944→                    }}
945→                  />
946→                  <div className="flex items-center justify-between px-3 pb-2">
947→                    <span className="font-mono text-xs text-foreground-tertiary uppercase tracking-wider">
948→                      Enter to send / Shift+Enter for new line
949→                    </span>
950→                    <div className="flex items-center gap-2">
951→                      {conversation && (
952→                        <span className="font-mono text-xs text-foreground-tertiary">
953→                          {conversation.inputTokensTotal + conversation.outputTokensTotal} tokens
